import type { Column, Typed } from '../Column'
import type { DynamicValueDefinitions } from './Choice'
import type { TableName } from '../Table'

export type DecimalColumnType<
    Type extends number = number,
    Default extends Type = Type,
    ReferenceSchema extends TableName = TableName,
> = Column<Type, Default> & {
    /**
     * Number of decimal places to display.
     * Controls the precision of the decimal number.
     */
    scale?: number
} & (
        | {
              /** Object literal, specify type and then relevant additional parameters for reference choices and script defaults*/
              dynamicValueDefinitions?: DynamicValueDefinitions<ReferenceSchema>
              /** @deprecated Use dynamicValueDefinitions instead */
              dynamic_value_definitions?: never
          }
        | {
              /** Object literal, specify type and then relevant additional parameters for reference choices and script defaults*/
              dynamicValueDefinitions?: never
              /** @deprecated Use dynamicValueDefinitions instead */
              dynamic_value_definitions?: DynamicValueDefinitions<ReferenceSchema>
          }
    )

/**
 * A Column for a decimal type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @group Table/Columns
 */
export function DecimalColumn<
    const Type extends number,
    const Default extends Type,
    const C extends DecimalColumnType<Type, Default>,
>(config: C & DecimalColumnType<Type, Default>) {
    return config as Typed<Type, C>
}
